const active=new WeakMap();
const smooth=(a,b,v)=>{const t=Math.max(0,Math.min(1,(v-a)/(b-a)));return t*t*(3-2*t);};
export function correctPrincipalHipWeights(model){
 if(active.has(model))throw new Error('Principal hip weights already corrected');
 const mesh=model?.getObjectByName('PrincipalBody'),source=mesh?.geometry;if(!mesh?.isSkinnedMesh||!source?.attributes.skinWeight)throw new Error('Approved principal skin required');
 const names=mesh.skeleton.bones.map(b=>b.name),index=name=>{const i=names.indexOf(name);if(i<0)throw new Error('Principal joint missing: '+name);return i;},hand=index('HandR'),pelvis=index('Pelvis'),spine=index('Spine'),thigh=index('ThighR'),p=source.attributes.position;
 // Validate every target before mutation. The original source accidentally used
 // x>.4 && .43<height<.68 as a whole-hand box, catching four rigid hip points; the broad arm mask also contaminated their blended hip neighbors.
 for(const {vertex,position,before}of TARGETS){
  const actual=[0,1,2,3].map(k=>[names[source.attributes.skinIndex.getComponent(vertex,k)],source.attributes.skinWeight.getComponent(vertex,k)]).filter(([,w])=>w>0);
  if(vertex>=p.count||position.some((v,k)=>Math.abs(v-p.getComponent(vertex,k))>1e-7)||JSON.stringify(actual)!==JSON.stringify(before))throw new Error('Principal hip repair does not match the approved source at '+vertex);
 }

 const geometry=source.clone(),changes=[];
 for(const{vertex,position,before}of TARGETS){
  const y=position[1],pelvisBlend=smooth(.48,.63,y),spineBlend=smooth(.62,1.05,y),weights=(y<.59?[[thigh,1-pelvisBlend],[pelvis,pelvisBlend]]:[[pelvis,1-spineBlend],[spine,spineBlend]]).filter(([,w])=>w>0);
  // These are the original generator's lower-body/torso branches, evaluated
  // without its erroneous hand-box early return. The genuine paw is untouched.
  geometry.attributes.skinIndex.setXYZW(vertex,weights[0][0],weights[1]?.[0]??0,0,0);geometry.attributes.skinWeight.setXYZW(vertex,weights[0][1],weights[1]?.[1]??0,0,0);
  changes.push({vertex,position:[...position],before:before.map(([joint,weight])=>({joint,weight})),after:weights.map(([joint],k)=>({joint:names[joint],weight:geometry.attributes.skinWeight.getComponent(vertex,k)}))});
 }
 geometry.attributes.skinIndex.needsUpdate=true;geometry.attributes.skinWeight.needsUpdate=true;
 const vertices=new Set(TARGETS.map(t=>t.vertex)),affectedTriangles=[];for(let i=0;i<source.index.count;i+=3)if([0,1,2].some(k=>vertices.has(source.index.getX(i+k))))affectedTriangles.push(i/3);
 const report=Object.freeze({vertexCount:changes.length,triangleCount:affectedTriangles.length,changes,affectedTriangles,untouchedNearWristVertex:4887});
 mesh.geometry=geometry;let disposed=false;
 const result={report,geometry,originalGeometry:source,dispose(){if(disposed)return;disposed=true;if(mesh.geometry===geometry)mesh.geometry=source;geometry.dispose();active.delete(model);}};active.set(model,result);return result;
}
